def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='El Romanticismo rompe con el neoclasicismo y defiende la libertad, el sentimiento y la imaginación. Este capítulo estudia el Romanticismo español a través de sus autores principales: Larra, que lo vive como periodismo crítico; Espronceda y el Duque de Rivas, que lo viven como rebeldía; Zorrilla, que lo lleva al teatro popular; y Bécquer y Rosalía de Castro, que lo convierten en poesía íntima. El lector aprenderá a reconocer los rasgos del movimiento y a comentar un poema, un artículo y un fragmento dramático.',
        quotes=[Q('es_romanticismo', 'El Romanticismo es un movimiento revolucionario en todos los ámbitos vitales que, en las artes, rompe con los esquemas establecidos en el Neoclasicismo'), Q('en_romanticism', 'Spanish Romanticism also influenced regional literatures.')]))
    P.append(dict(text='Un movimiento tardío y breve\nEl Romanticismo defiende la fantasía, la imaginación y las fuerzas irracionales del espíritu. Sus precursores son Rousseau y Goethe, y su lema es la libertad en todos los aspectos de la vida; buscan obras menos perfectas y menos regulares, pero más profundas e íntimas. En España fue tardío y breve, y más intenso, pues la segunda mitad del siglo XIX la acapara el Realismo. La fuente señala que el romanticismo español es complejo y confuso, con contradicciones que van de la rebeldía revolucionaria al retorno a la tradición católico-monárquica. La fuente inglesa observa que hay autores que consideran el romanticismo español uno de los más tempranos de Europa y otros que dudan de que España llegara a tener un periodo romántico literario.',
        quotes=[Q('es_romanticismo', 'Los precursores del Romanticismo, que se extendió por Europa y América, son Rousseau (1712-1778) y el dramaturgo alemán Goethe (1749-1832).'), Q('es_romanticismo', 'El Romanticismo en España fue tardío y breve, más intenso'), Q('es_romanticismo', 'con grandes contradicciones que comprenden desde la rebeldía y las ideas revolucionarias hasta el retorno a la tradición católico-monárquica'), Q('en_romanticism', 'This notion is the subject of debate for there are authors who stress that Spain\'s romanticism is one of the earliest in Europe')]))
    P.append(dict(text='Rasgos del Romanticismo\nLa literatura romántica rechaza el neoclasicismo: combina géneros y versos de distinta medida, desprecia las tres unidades en el teatro y alterna lo cómico con lo dramático. Subjetivismo: el autor vierte en la obra sus sentimientos de insatisfacción ante un mundo que frena sus ansias, y la naturaleza se funde con su estado de ánimo. Atracción por lo nocturno y misterioso: ruinas, bosques, cementerios, lo sobrenatural. Fuga del mundo burgués hacia épocas pasadas, sobre todo la Edad Media, o hacia lo exótico. En poesía se proclama el derecho a usar todas las variaciones métricas, lo que anticipa las audacias modernistas. Los temas son el yo, el amor pasional, la historia y la leyenda, la religión (a veces a través de la rebeldía), las reivindicaciones sociales, la naturaleza y la sátira.',
        quotes=[Q('es_romanticismo', 'Rechazo al Neoclasicismo.'), Q('es_romanticismo', 'Subjetivismo. Sea cual sea el género de la obra, el alma exaltada del autor vierte en ella todos sus sentimientos de insatisfacción'), Q('es_romanticismo', 'Atracción por lo nocturno y misterioso.'), Q('es_romanticismo', 'Frente a los neoclásicos, que admiraban la antigüedad grecolatina, los románticos prefieren la Edad Media y el Renacimiento.'), Q('es_romanticismo', 'El amor pasional, con entregas súbitas, totales, y rápidos abandonos.'), Q('en_romanticism', 'Romanticists rejected the social conventions of the time in favour of a moral outlook known as individualism.')]))
    P.append(dict(text='Cómo llegó a España\nEl Romanticismo penetra en España por Andalucía y por Cataluña. En Andalucía, Juan Nicolás Böhl de Faber publicó en 1818 y 1819 artículos en defensa del teatro español del Siglo de Oro, tan atacado por los neoclásicos; en Cataluña, la revista El Europeo (Barcelona, 1823-1824) defendió un romanticismo moderado y tradicionalista y negó los valores del neoclasicismo. La fuente distingue una vertiente tradicional, que exalta el Cristianismo, el Trono y la Patria, y en la que sitúa a Walter Scott, Chateaubriand, el Duque de Rivas y Zorrilla. El Duque de Rivas y Espronceda se iniciaron en la postura neoclásica y se convirtieron al Romanticismo.',
        quotes=[Q('es_romanticismo', 'El Romanticismo penetra en España por Andalucía y por Cataluña (El Europeo)'), Q('es_romanticismo', 'El Europeo fue una revista publicada en Barcelona entre 1823 y 1824'), Q('es_romanticismo', 'Exaltan, pues, el Cristianismo, el Trono y la Patria, como máximos valores.'), Q('es_romanticismo', 'como el Duque de Rivas o José de Espronceda'), Q('en_romanticism', 'Romanticism in Spanish literature developed a well-known literature with a huge variety of poets and playwrights.')]))
    P.append(dict(text='El costumbrismo\nEl costumbrismo fija su atención en los hábitos contemporáneos, principalmente desde el punto de vista de las clases populares, y se expresa en un lenguaje purista y castizo. Su principal autor es Mesonero Romanos, que se situó al margen del Romanticismo y con una postura irónica ante él. Surgió en el seno del Romanticismo como signo de melancolía por los valores del pasado y contribuyó a su decadencia y al inicio del Realismo, cuando se aburguesó y se convirtió en un método descriptivo. Larra practica el artículo costumbrista, pero le da una intención crítica y satírica que lo aleja de la simple descripción.',
        quotes=[Q('es_romanticismo', 'El costumbrismo fija su atención en los hábitos contemporáneos, principalmente desde el punto de vista de las clases populares'), Q('es_romanticismo', 'El principal autor costumbrista es Mesonero Romanos'), Q('es_romanticismo', 'contribuyó a la decadencia del movimiento romántico y al inicio del Realismo'), Q('es_larra', 'Periodista, crítico satírico y literario, y escritor costumbrista, publicó en prensa más de doscientos artículos a lo largo de ocho años.')]))
    P.append(dict(text='Larra, Fígaro\nMariano José de Larra (Madrid, 1809-1837) es considerado, junto con Espronceda, Bécquer, Zorrilla y Rosalía de Castro, la más alta cota del Romanticismo literario español. Periodista, crítico satírico y escritor costumbrista, publicó más de doscientos artículos en ocho años bajo los seudónimos de Fígaro, el Duende, el Bachiller y el Pobrecito Hablador, e impulsó así el ensayo. Sus ideas tienen origen en la Ilustración y en Cadalso, y fueron muy influyentes en el 98: en 1901, Azorín, Unamuno y Baroja llevaron una corona de flores a su tumba. Murió el 13 de febrero de 1837, tras la última ruptura con Dolores Armijo. La fuente inglesa destaca que escribía con gran rapidez y con el miedo constante a la censura.',
        quotes=[Q('es_larra', 'Es considerado, junto con Espronceda, Bécquer, José Zorrilla y Rosalía de Castro, la más alta cota del Romanticismo literario español.'), Q('es_larra', 'Escribió bajo los seudónimos Fígaro, el Duende, Bachiller y el Pobrecito Hablador.'), Q('es_larra', 'Las ideas de Larra tienen su origen en la Ilustración española, en especial en José Cadalso'), Q('es_larra', 'En 1901 algunos de los representantes de dicha generación, como Azorín, Unamuno y Baroja, llevaron una corona de flores a su tumba'), Q('en_larra', 'He wrote at great speed with the constant fear of censor before his eyes')]))
    P.append(dict(text='«Vuelva usted mañana»\nEl artículo comienza con un extranjero, monsieur Sans-délai, que llega a Madrid con un negocio que cree resolver en quince días. El relato muestra cómo cada gestión se aplaza con la misma frase: «Vuelva usted mañana». Un genealogista, un traductor, un escribiente, un sastre y hasta una planchadora cumplen un plazo tras otro, y el francés se desespera: «¿Qué os parece de esta tierra, monsieur Sans-délai?» —«Me parece que son hombres singulares...». Larra convierte la costumbre en crítica de la pereza y de la ineficacia, sin la ternura del costumbrismo: la anécdota es siempre un diagnóstico de la sociedad. La fuente en español señala que ataca la organización del Estado y se burla de la sociedad.',
        quotes=[Q('ws_larra_vuelva', 'Vuelva usted mañana- nos respondió la criada-, porque el señor no se ha levantado todavía.'), Q('ws_larra_vuelva', '¿Qué os parece de esta tierra, monsieur Sans-délai?'), Q('ws_larra_vuelva', 'Me parece que son hombres singulares...'), Q('es_larra', 'En sus artículos combate la organización del Estado, ataca al absolutismo y al carlismo, se burla de la sociedad'), Q('en_larra', 'His works were often satirical and critical of the 19th-century Spanish society')]))
    P.append(dict(text='Espronceda, el poeta de la rebeldía\nJosé de Espronceda (Almendralejo, 1808-Madrid, 1842) es considerado el poeta más representativo del primer Romanticismo español. De joven, con quince años, fundó con sus amigos la sociedad secreta Los Numantinos contra Fernando VII, y sufrió reclusión por ello. Vivió el exilio liberal y su amor por Teresa Mancha, que inspiró el Canto a Teresa, «una desgarradora confesión de amor y desengaño». Sus temas son la libertad, el amor, la rebeldía y la muerte, y su estilo, vehemente y musical, aprovecha todos los metros. La fuente inglesa lo describe como un poeta romántico y uno de los autores más representativos del siglo XIX; sus restos reposan desde 1902 en el Panteón de Hombres Ilustres.',
        quotes=[Q('es_espronceda', 'considerado el poeta más representativo del primer Romanticismo en España'), Q('es_romanticismo', 'Sufrió reclusión por ello.'), Q('es_romanticismo', 'Fue Espronceda, dejando en su Canto a Teresa una desgarradora confesión de amor y desengaño'), Q('en_espronceda', 'was a Romantic Spanish poet, one of the most representative authors of the 19th century'), Q('en_espronceda', 'In 1902, his body was moved to Panteón de Hombres Ilustres, Spain.')]))
    P.append(dict(text='La canción del pirata\nLa Canción del pirata se publicó por primera vez en El Artista en 1835 y de nuevo en las Poesías de 1840. Exalta a un pirata como ejemplo de personalidad que vive al margen de la sociedad, despreciando las convenciones y los bienes materiales, y cuyo máximo ideal es la libertad: «Que es mi barco mi tesoro, / que es mi Dios la libertad, / mi ley la fuerza y el viento, / mi única patria la mar». El poema abre con la imagen del velero que «no corta el mar, sino vuela» y se estructura en estrofas de versos octosílabos y tetrasílabos, con estribillo. La fuente indica que se inspira en un poema de Fontan o en una imitación de Byron, aunque la crítica coincide en que los supera.',
        quotes=[Q('es_pirata', 'Canción del pirata es un poema escrito por José de Espronceda y publicado por primera vez en la revista El Artista en 1835.'), Q('es_pirata', 'exalta a un pirata como ejemplo de personalidad que vive al margen de la sociedad'), Q('ws_pirata', 'Con diez cañones por banda,', 'Mi velero bergantin:'), Q('ws_pirata', 'Que es mi barco mi tesoro.', 'Mi única patria la mar.'), Q('es_pirata', 'Toda la crítica concuerda sin embargo en que supera a estos textos.')]))
    P.append(dict(text='El Canto a Teresa\nEl Canto a Teresa es la gran confesión íntima de Espronceda. Empieza con una pregunta retórica: «¿Por qué volvéis a la memoria mía, / tristes recuerdos del placer perdido, / a aumentar la ansiedad y la agonía / de este desierto corazón herido?». Evoca las horas de juventud y amor, con el paisaje en armonía con el ánimo (ruiseñores, sol, aura, bosque, fuentes), y después descubre el engaño: la vida es como una nave que sale con orgullo del puerto. Es una muestra del subjetivismo romántico: el poeta vuelca su insatisfacción, el pasado y el desengaño, en octavas reales, estrofa italiana asumida por la lírica romántica. Es el contrapunto íntimo de la fuerza épica de la Canción del pirata.',
        quotes=[Q('ws_teresa', '¿Por qué volvéis a la memoria mía?,', 'de este desierto corazón herido?'), Q('ws_teresa', 'Gorjeaban los dulces ruiseñores,', 'el bosque mansamente respondía,'), Q('es_romanticismo', 'El Yo, la propia intimidad.'), Q('es_romanticismo', 'Subjetivismo. Sea cual sea el género de la obra')]))
    P.append(dict(text='El Duque de Rivas y Don Álvaro\nÁngel de Saavedra, duque de Rivas (Córdoba, 1791-Madrid, 1865), fue dramaturgo, poeta, historiador, pintor y estadista, y hoy es conocido por su drama romántico Don Álvaro o la fuerza del sino (1835), que la fuente inglesa llama el primer gran drama romántico español. Condenado a muerte en 1823 por sus ideas liberales, huyó a Inglaterra, vivió en Italia, Malta y Francia y volvió tras la amnistía de 1834. Su leyenda El moro expósito (1834), sobre los infantes de Lara, se considera pieza fundacional del Romanticismo en España. Es un ejemplo de poeta que pasa del neoclasicismo a un romanticismo que combina verso y prosa y desprecia las unidades.',
        quotes=[Q('es_rivas', 'que hoy goza de notoriedad por su drama romántico Don Álvaro o la fuerza del sino (1835)'), Q('es_rivas', 'considerada pieza fundacional del romanticismo en España'), Q('en_rivas', 'In 1823, Rivas was condemned to death for his liberal views and fled to England.'), Q('es_romanticismo', 'se convirtieron ávidamente al Romanticismo, como el Duque de Rivas o José de Espronceda')]))
    P.append(dict(text='Zorrilla y Don Juan Tenorio\nJosé Zorrilla (Valladolid, 1817-Madrid, 1893) es una de las principales figuras del Romanticismo español, coronado poeta nacional en Granada en 1889. Su drama religioso-fantástico Don Juan Tenorio, estrenado en 1844, es la versión más romántica del mito de don Juan. En la primera parte, el protagonista sigue siendo el libertino que describe Tirso; en la segunda, el amor de doña Inés lo salva. La fuente inglesa cuenta la apuesta inicial entre don Juan y don Luis en una taberna de Sevilla. Zorrilla llevó el verso y la leyenda a un público muy amplio. Aún hoy la obra se representa cada año, el Día de Todos los Santos.',
        quotes=[Q('es_zorrilla', 'Autor del drama romántico Don Juan Tenorio, es una de las principales figuras del Romanticismo literario español.'), Q('es_zorrilla', 'lo coronan de laurel como poeta nacional en Granada en 1889'), Q('en_tenorio', 'is a play written by José Zorrilla and produced in 1844'), Q('en_tenorio', 'It is the most romantic of the two principal Spanish-language literary interpretations of the legend of Don Juan.'), Q('en_zorrilla', 'was a Spanish poet and dramatist, who became National Laureate')]))
    P.append(dict(text='Bécquer, la poesía íntima\nGustavo Adolfo Bécquer (Sevilla, 1836-Madrid, 1870) es el poeta y narrador del posromanticismo español; sus Rimas y Leyendas constituyen uno de los libros más populares de la literatura hispana. La fuente inglesa lo considera el fundador de la lírica española moderna y destaca su influencia en Cernuda, Machado, Paz y Jiménez. Su poesía «despoja la expresión de lo ampuloso o histriónico» y abre una voz poética nueva, a la que volverán Antonio Machado, Martí o Neruda. Él mismo escribió que «la poesía popular es la síntesis de la poesía». Con Bécquer, el Romanticismo exaltado de Espronceda se convierte en una poesía de tono menor, sencilla y esencial.',
        quotes=[Q('es_becquer', 'Sus Rimas y Leyendas, un conjunto de poemas y relatos reunidos, constituyen uno de los libros más populares de la literatura hispana.'), Q('en_becquer', 'His work approached the traditional poetry and themes in a modern way, and he is considered the founder of modern Spanish lyricism.'), Q('es_rimas', 'la depuración del Romanticismo que el poeta sevillano realizó, despojando la expresión de lo ampuloso o histriónico'), Q('es_rimas', 'la poesía popular es la síntesis de la poesía')]))
    P.append(dict(text='El Libro de los gorriones\nLas Rimas se conservan gracias a un manuscrito, el Libro de los gorriones, que Bécquer firmó en 1868 y que se conserva en la Biblioteca Nacional. El poeta había confiado el libro original a su protector Luis González Bravo, y se perdió cuando se saqueó su casa en la revolución de 1868; Bécquer reescribió las Rimas de memoria. Tras su muerte, las Rimas se publicaron en 1871 y el hispanista Franz Schneider dio a conocer el manuscrito en 1914, lo que obligó a revisar el texto. La edición revisada de Rafael Montesinos (1995) presenta la Introducción sinfónica y 76 rimas. Obra «universalmente reconocida como la más honda y fina poesía del siglo XIX, en tono menor», fue ridiculizada por Núñez de Arce y elogiada por Antonio Machado.',
        quotes=[Q('es_rimas', 'Bécquer dejó compuesto el manuscrito titulado Libro de los gorriones'), Q('es_rimas', 'En 1914, el hispanista Franz Schneider'), Q('es_rimas', 'presenta el cuerpo ‘definitivo’ de las Rimas incluyendo la Introducción Sinfónica escrita por Bécquer, seguida de 76 rimas'), Q('es_rimas', 'fue ridiculizada por Núñez de Arce, elogiada por Antonio Machado'), Q('en_becquer', 'The first edition of their effort was published in 1871, and a second volume was published six years later.')]))
    P.append(dict(text='Qué es poesía\nLa rima I, «Yo sé un himno gigante y extraño», plantea la dificultad de escribir lo inefable: el poeta querría escribir con palabras «que fuesen a un tiempo / suspiros y risas, colores y notas», pero «no hay cifra / capaz de encerrarlo». La rima IV, «No digáis que, agotado su tesoro...», responde que habrá poesía «mientras haya un misterio para el hombre». La rima XXI es la definición más famosa: «¿Qué es poesía? —dices mientras clavas / en mi pupila tu pupila azul; / ¿Qué es poesía? ¿Y tú me lo preguntas? / Poesía... eres tú». Son tres poemas breves con una misma idea: la poesía no es un conjunto de reglas sino la emoción que despiertan la naturaleza y el amor.',
        quotes=[Q('ws_rima1', 'Con palabras que fuesen á un tiempo', 'Suspiros y risas, colores y notas.'), Q('ws_rima4', 'Mientras haya un misterio para el hombre,', '¡Habrá poesía!'), Q('ws_rima21', '¿Qué es poesía? dices mientras clavas', 'Poesía... eres tú.'), Q('es_rimas', 'Manuel Altolaguirre consideró la poesía de Bécquer como la más humana del Romanticismo español.')]))
    P.append(dict(text='Las golondrinas\nLa rima LIII, «Volverán las oscuras golondrinas», es una de las más célebres. Su estructura es paralelística: tres estrofas empiezan con «Volverán» (las golondrinas, las madreselvas, las palabras ardientes del amor) y cada una se cierra con el verso «Esas... ¡no volverán!», que contrapone lo que vuelve (la naturaleza, las palabras) a lo que no vuelve: «aquellas que aprendieron nuestros nombres», el amor vivido. El ritmo es el de una cuarteta con versos largos y cortos alternos, casi una canción, y el vocabulario es sencillo. Aquí aparecen los rasgos de Bécquer: musicalidad, sencillez, melancolía y la tensión entre el ciclo natural y el tiempo irreversible.',
        quotes=[Q('ws_rima53', 'Volverán las oscuras golondrinas', 'Jugando llamarán.'), Q('ws_rima53', 'Aquellas que aprendieron nuestros nombres...', 'Esas... ¡no volverán!'), Q('ws_rima53', 'Volverán las tupidas madreselvas', 'Sus flores se abrirán;'), Q('es_rimas', 'Cronológica y estilísticamente situado en el nacimiento de la poesía moderna')]))
    P.append(dict(text='La muerte en las Rimas\nLa rima LXXIII, «Cerraron sus ojos», describe la muerte desde fuera, con una sobriedad casi cinematográfica: cierran los ojos, cubren la cara con un lienzo, unos sollozan y otros callan, la luz proyecta en el muro la sombra del lecho y el cuerpo se dibuja rígido. Al amanecer, el pueblo despierta con sus ruidos y el contraste entre la vida y el misterio de la muerte cierra el poema. La enumeración de acciones breves en versos cortos y la ausencia de adjetivos hacen que la emoción venga de los hechos y no de la exclamación. Es un buen ejemplo de la depuración del Romanticismo que se atribuye a Bécquer.',
        quotes=[Q('ws_rima73', 'Cerraron sus ojos', 'Con un blanco lienzo;'), Q('ws_rima73', 'La luz, que en un vaso', 'La forma del cuerpo.'), Q('ws_rima73', 'Despertaba el día,', 'Despertaba el pueblo.'), Q('es_rimas', 'despojando la expresión de lo ampuloso o histriónico')]))
    P.append(dict(text='Rosalía de Castro\nRosalía de Castro (Santiago de Compostela, 1837-Padrón, 1885) es una de las grandes figuras de la lírica del siglo XIX, escribió en gallego y en castellano y es icono cultural de Galicia. Sus tres obras clave son Cantares gallegos (1863), considerada la primera gran obra de la literatura gallega contemporánea, Follas novas y En las orillas del Sar. Su poesía se caracteriza por la saudade, una combinación de nostalgia y anhelo. Está en el Rexurdimento gallego junto a Curros Enríquez y Pondal. Con Bécquer, representa la poesía íntima del posromanticismo y anticipa la lírica del siglo XX.',
        quotes=[Q('es_rosalia', 'Su poemario Cantares gallegos está valorado como la primera gran obra de la literatura gallega contemporánea.'.replace('Su poemario Cantares gallegos está','Su poemario Cantares gallegos​está')), Q('es_rosalia', 'Rosalía publicó Cantares gallegos en 1863'), Q('es_rosalia', 'Cantares gallegos, Follas novas y En las orillas del Sar'), Q('en_rosalia', 'was a Galician poet and novelist, considered one of the most important figures of the 19th-century Spanish literature and modern lyricism'), Q('en_rosalia', 'Her poetry is marked by saudade')]))
    P.append(dict(role='definition', text='Romanticismo: movimiento que rompe con el neoclasicismo y defiende la libertad, el sentimiento, la imaginación y la individualidad; en literatura mezcla géneros y metros, desprecia las unidades teatrales y prefiere lo medieval, lo nocturno y lo misterioso.',
        quotes=[Q('es_romanticismo', 'defendiendo la fantasía, la imaginación y las fuerzas irracionales del espíritu'), Q('es_romanticismo', 'Rechazo al Neoclasicismo.'), Q('en_romanticism', 'Romanticism was a complex movement with a variety of viewpoints that permeated Western civilization across the globe.')]))
    P.append(dict(role='consejo', text='Cuando comente un texto romántico, busque primero el yo: quién habla y qué siente. Después identifique el escenario (noche, mar, ruinas), los símbolos (golondrinas, barco) y la forma métrica, y pregunte qué ha cambiado respecto al neoclasicismo: la inspiración, la libertad formal y la emoción sustituyen a la razón y a la regla.',
        quotes=[Q('es_romanticismo', 'Subjetivismo. Sea cual sea el género de la obra, el alma exaltada del autor vierte en ella todos sus sentimientos de insatisfacción'), Q('ws_rima53', 'Volverán las oscuras golondrinas', 'Jugando llamarán.')]))
    P.append(dict(role='self_check', text='¿Qué rasgos distinguen el Romanticismo del neoclasicismo? ¿Qué diferencia hay entre el costumbrismo y la crítica de Larra? ¿Qué ideal defiende el pirata de Espronceda? ¿Qué ha cambiado entre Espronceda y Bécquer? ¿Cómo está construida la rima LIII?',
        quotes=[Q('es_romanticismo', 'Los precursores del Romanticismo, que se extendió por Europa y América, son Rousseau (1712-1778) y el dramaturgo alemán Goethe (1749-1832).'), Q('es_rimas', 'despojando la expresión de lo ampuloso o histriónico')]))
    return P


